import{_ as r,C as i,o as e,c as h,a2 as a,b as n,w as l,a as s,E as d,a3 as u}from"./chunks/framework.Crpw6aS5.js";const x=JSON.parse('{"title":"航空公司教训","description":"投资生涯最深刻的错误之一，最糟糕的生意模式","frontmatter":{"title":"航空公司教训","description":"投资生涯最深刻的错误之一，最糟糕的生意模式"},"headers":[],"relativePath":"02_concepts/airline-lessons.md","filePath":"02_concepts/airline-lessons.md"}'),q={name:"02_concepts/airline-lessons.md"};function c(b,t,f,p,m,g){const o=i("Mermaid");return e(),h("div",null,[t[1]||(t[1]=a('<h1 id="航空公司教训" tabindex="-1">航空公司教训 <a class="header-anchor" href="#航空公司教训" aria-label="Permalink to &quot;航空公司教训&quot;">​</a></h1><blockquote><p>&quot;最糟糕的企业就是那种增长很快，需要大量资本才能实现增长，然后赚不到什么钱。想想航空公司。&quot; —— <a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2007年</p></blockquote><p>1989年，巴菲特以&quot;我知道航空公司在赚什么钱&quot;的自信买入了<a href="/search.html?q=美国航空">美国航空</a>优先股。1991年，这笔投资差点归零。这是他投资生涯中最重要的错误之一，也是理解&quot;最糟糕生意模式&quot;的最佳教材。</p><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1989年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">买入美国航空可转换优先股</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1991年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">行业危机，优先股价值大幅减值</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1994年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">深刻反思：成本结构的历史问题</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1998年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">幸运脱身，高价卖出</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2007年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">&quot;三种储蓄账户&quot;经典论述</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2013年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">再次强调：铁路vs航空的本质差异</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2020年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">疫情后清仓航空股</td></tr></tbody></table><hr><h2 id="一、1989年-买入决策与背景" tabindex="-1">一、1989年：买入决策与背景 <a class="header-anchor" href="#一、1989年-买入决策与背景" aria-label="Permalink to &quot;一、1989年：买入决策与背景&quot;">​</a></h2><h3 id="投资细节" tabindex="-1">投资细节 <a class="header-anchor" href="#投资细节" aria-label="Permalink to &quot;投资细节&quot;">​</a></h3><p>1989年夏天，巴菲特卖出了中期免税债券，买入了三家可转换优先股：</p><blockquote><p>&quot;我们夏天买了六亿六千万<a href="/03_companies/吉列.html">吉列</a>，八年强制赎回，股息八又四分之三，五十块转股，然后三亿五千八百万<a href="/search.html?q=美国航空">美国航空</a>，九年赎回，股息九又四分之一，六十块转股。&quot;</p></blockquote><h3 id="巴菲特的自知之明" tabindex="-1">巴菲特的自知之明 <a class="header-anchor" href="#巴菲特的自知之明" aria-label="Permalink to &quot;巴菲特的自知之明&quot;">​</a></h3><blockquote><p>&quot;和传统可转优先股不一样，我们买这些不能短期卖，一段时间不能转，所以短期价格波动赚不到钱。我们最终赚钱还是要看企业长期经营结果好不好。我们不知道投行、航空、造纸未来经济怎么样，我们不是无神论，我们是不可知论，我们没有强烈 conviction。&quot;</p></blockquote><p><strong>核心教训</strong>：承认不确定性的前提下仍然投资，本身就是冒险。</p><hr><h2 id="二、1990-1994年-危机的根源" tabindex="-1">二、1990-1994年：危机的根源 <a class="header-anchor" href="#二、1990-1994年-危机的根源" aria-label="Permalink to &quot;二、1990-1994年：危机的根源&quot;">​</a></h2><h3 id="_1991年-行业全面亏损" tabindex="-1">1991年：行业全面亏损 <a class="header-anchor" href="#_1991年-行业全面亏损" aria-label="Permalink to &quot;1991年：行业全面亏损&quot;">​</a></h3><blockquote><p>&quot;我们<a href="/search.html?q=美国航空">美国航空</a>优先股价值低于成本，因为航空业全行业亏，破产公司还在运营，所以正常公司竞争不过，因为破产公司不用承担过去成本，能低价卖票，把整个行业价格拉下来。&quot;</p></blockquote><h3 id="_1994年-最深刻的反思" tabindex="-1">1994年：最深刻的反思 <a class="header-anchor" href="#_1994年-最深刻的反思" aria-label="Permalink to &quot;1994年：最深刻的反思&quot;">​</a></h3><blockquote><p>&quot;在这次购买之前，我根本没有关注那些成本高昂且极难降低的航空公司将不可避免地会遇到的问题。早些年，这些威胁生命的成本几乎没有造成什么问题。航空公司当时受到监管的保护免受竞争，运营商可以吸收高成本，因为他们可以通过同样高的票价将其转嫁出去。&quot;</p></blockquote><blockquote><p>&quot;当放松管制来临时，它并没有立即改变局面：低成本运营商的运力很小，高成本航空公司可以在很大程度上维持其现有的票价结构。在此期间，长期问题很大程度上不可见但缓慢转移，不可持续的成本进一步嵌入。&quot;</p></blockquote><blockquote><p>&quot;随着低成本运营商的运力扩张，他们的票价开始迫使老牌高成本航空公司削减自己的票价。最终经济学的基本原理占了上风：在不受监管的大宗商品业务中，公司必须将其成本降低到竞争水平或面临灭绝。这个原则对你的董事长来说应该是显而易见的，但我错过了它。&quot;</p></blockquote><hr><h2 id="三、1998年-幸运脱身" tabindex="-1">三、1998年：幸运脱身 <a class="header-anchor" href="#三、1998年-幸运脱身" aria-label="Permalink to &quot;三、1998年：幸运脱身&quot;">​</a></h2><blockquote><p>&quot;我，说出来惭愧，1989年我也参与了这种愚蠢，让<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>买入了<a href="/search.html?q=美国航空">美国航空</a>优先股。墨水还没干，公司就开始螺旋下降，很快分红就停了。后来我们非常幸运，1998年居然能高价卖掉股份，赚了一笔。&quot;</p></blockquote><blockquote><p>&quot;我卖出之后十年，公司破产了两次。&quot;</p></blockquote><p><strong>关键点</strong>：这笔&quot;成功&quot;完全归功于运气，而非判断力的改善。</p><hr><h2 id="四、2007年-最经典的总结" tabindex="-1">四、2007年：最经典的总结 <a class="header-anchor" href="#四、2007年-最经典的总结" aria-label="Permalink to &quot;四、2007年：最经典的总结&quot;">​</a></h2><h3 id="三种储蓄账户理论" tabindex="-1">三种储蓄账户理论 <a class="header-anchor" href="#三种储蓄账户理论" aria-label="Permalink to &quot;三种储蓄账户理论&quot;">​</a></h3><blockquote><p>&quot;总结一下，想想三种储蓄账户：</p><ul><li>好账户：给你非常高的利率，随着年份增长利率还会上升</li><li>不错账户：给你有吸引力的利率，你增加存款也能赚利息</li><li>糟糕账户：给你不足的利率，还要求你不断加钱，才能拿到那些令人失望的回报&quot;</li></ul></blockquote><blockquote><p>&quot;航空业就是第三种。&quot;</p></blockquote><h3 id="关于航空业的资本黑洞本质" tabindex="-1">关于航空业的资本黑洞本质 <a class="header-anchor" href="#关于航空业的资本黑洞本质" aria-label="Permalink to &quot;关于航空业的资本黑洞本质&quot;">​</a></h3><blockquote><p>&quot;从莱特兄弟时代开始，航空业一直对资本有着永无止境的需求。事实上，如果一个有远见的资本家当时在场的话，他应该在奥维尔起飞的时候就把飞机打下来，那样他的继任者们会省下很多钱。&quot;</p></blockquote><hr><h2 id="五、2013年-铁路与航空的本质差异" tabindex="-1">五、2013年：铁路与航空的本质差异 <a class="header-anchor" href="#五、2013年-铁路与航空的本质差异" aria-label="Permalink to &quot;五、2013年：铁路与航空的本质差异&quot;">​</a></h2><p>巴菲特在讨论<a href="/03_companies/BNSF铁路.html">BNSF铁路</a>时，对比了铁路与航空的根本差异：</p><blockquote><p>&quot;<a href="/03_companies/BNSF铁路.html">BNSF铁路</a>承运约15%（按吨英里计算）的所有城际货物。用一加仑柴油运送一吨货物约500英里，承担同样工作的卡车消耗的燃料约为四倍。&quot;</p></blockquote><h3 id="关键差异" tabindex="-1">关键差异 <a class="header-anchor" href="#关键差异" aria-label="Permalink to &quot;关键差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">铁路（BNSF）</th><th style="text-align:left;">航空业</th></tr></thead><tbody><tr><td style="text-align:left;">定价权</td><td style="text-align:left;">有</td><td style="text-align:left;">无</td></tr><tr><td style="text-align:left;">资本回报</td><td style="text-align:left;">稳定、可预期</td><td style="text-align:left;">永无止境的资本需求</td></tr><tr><td style="text-align:left;">竞争格局</td><td style="text-align:left;">区域垄断</td><td style="text-align:left;">大宗商品竞争</td></tr><tr><td style="text-align:left;">护城河</td><td style="text-align:left;">深厚</td><td style="text-align:left;">几乎没有</td></tr></tbody></table><hr><h2 id="六、2020年-再次清仓" tabindex="-1">六、2020年：再次清仓 <a class="header-anchor" href="#六、2020年-再次清仓" aria-label="Permalink to &quot;六、2020年：再次清仓&quot;">​</a></h2><p>新冠疫情爆发后，巴菲特在2020年股东大会上宣布伯克希尔已清仓所有美国航空公司股票：</p><blockquote><p>&quot;航空业是世界变化的一个例子。我不知道美国人现在是否会像以前那样多地飞行。&quot;</p></blockquote><p><strong>核心逻辑</strong>：当商业模式的基本假设被打破时，果断认错比坚持更明智。</p><hr><h2 id="十年演进总结" tabindex="-1">十年演进总结 <a class="header-anchor" href="#十年演进总结" aria-label="Permalink to &quot;十年演进总结&quot;">​</a></h2><h3 id="_1980年代-初尝苦果" tabindex="-1">1980年代：初尝苦果 <a class="header-anchor" href="#_1980年代-初尝苦果" aria-label="Permalink to &quot;1980年代：初尝苦果&quot;">​</a></h3><ul><li>1989年买入<a href="/search.html?q=美国航空">美国航空</a>优先股，自以为理解行业</li><li>低估了&quot;成本结构不可逆&quot;的致命性</li></ul><h3 id="_1990年代-深刻反思" tabindex="-1">1990年代：深刻反思 <a class="header-anchor" href="#_1990年代-深刻反思" aria-label="Permalink to &quot;1990年代：深刻反思&quot;">​</a></h3><ul><li>1991-1994年持续减值，最终承认&quot;错在我&quot;</li><li>1998年幸运脱身，但十年后公司破产两次</li></ul><h3 id="_2000年代-理论升华" tabindex="-1">2000年代：理论升华 <a class="header-anchor" href="#_2000年代-理论升华" aria-label="Permalink to &quot;2000年代：理论升华&quot;">​</a></h3><ul><li>2007年提出&quot;三种储蓄账户&quot;理论，航空业成为&quot;糟糕企业&quot;的教科书案例</li><li>明确指出增长快但需要大量资本的企业是最危险的陷阱</li></ul><h3 id="_2010年代-对比深化" tabindex="-1">2010年代：对比深化 <a class="header-anchor" href="#_2010年代-对比深化" aria-label="Permalink to &quot;2010年代：对比深化&quot;">​</a></h3><ul><li>2013年收购BNSF铁路后，系统对比铁路与航空的本质差异</li><li>定价权、资本回报稳定性成为核心判断标准</li></ul><h3 id="_2020年代-最终告别" tabindex="-1">2020年代：最终告别 <a class="header-anchor" href="#_2020年代-最终告别" aria-label="Permalink to &quot;2020年代：最终告别&quot;">​</a></h3><ul><li>2020年疫情后清仓所有航空股</li><li>60年投资生涯中，对航空业的认知从&quot;不懂&quot;到&quot;懂了不碰&quot;</li></ul><hr><h2 id="核心教训" tabindex="-1">核心教训 <a class="header-anchor" href="#核心教训" aria-label="Permalink to &quot;核心教训&quot;">​</a></h2><ol><li><p><strong>成本结构的可逆性是关键</strong>：高固定成本、强工会、价格竞争的行业几乎不可能获得合理回报</p></li><li><p><strong>增长不等于价值</strong>：航空业增长很快，但增长需要大量资本投入，股东最终一无所获</p></li><li><p><strong>护城河比增长更重要</strong>：没有定价权的行业，增长只会吸引更多竞争，利润率被持续侵蚀</p></li><li><p><strong>认错要及时</strong>：1998年&quot;幸运脱身&quot;是运气，2020年主动清仓是判断力的进步</p></li><li><p><strong>声誉不是护城河</strong>：优秀的管理层（如USAir的Seth Schofield）也无法挽救糟糕的行业结构</p></li></ol><hr><h2 id="主题关联" tabindex="-1">主题关联 <a class="header-anchor" href="#主题关联" aria-label="Permalink to &quot;主题关联&quot;">​</a></h2>',62)),(e(),n(u,null,{default:l(()=>[d(o,{id:"mermaid-405",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%E8%88%AA%E7%A9%BA%E5%85%AC%E5%8F%B8%E6%95%99%E8%AE%AD%5D%20--%3E%20B%5B%E7%94%9F%E6%84%8F%E6%A8%A1%E5%BC%8F%5D%0A%20%20%20%20A%20--%3E%20C%5B%E9%A3%8E%E9%99%A9%5D%0A%20%20%20%20A%20--%3E%20D%5B%E8%B5%84%E6%9C%AC%E9%85%8D%E7%BD%AE%5D%0A%20%20%20%20A%20--%3E%20E%5B%E9%94%99%E8%AF%AF%E4%B8%8E%E5%8F%8D%E6%80%9D%5D%0A%20%20%20%20A%20--%3E%20F%5B%E6%8A%A4%E5%9F%8E%E6%B2%B3%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/search.html?q=生意模式">生意模式</a> - 如何识别好生意与坏生意</li><li><a href="/02_concepts/capital-allocation.html">资本配置</a> - 如何评估资本密集型行业</li><li><a href="/search.html?q=错误与反思">错误与反思</a> - 从错误中学习的艺术</li><li><a href="/02_concepts/moat.html">护城河</a> - 为什么定价权比增长更重要</li></ul><hr><p><em>本页面整理自<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>致股东信原文（1957-2025年），慢慢变富的卡尔编辑整理</em></p>',5))])}const k=r(q,[["render",c]]);export{x as __pageData,k as default};
